    qu,
    ri,
    sa,
    sg,
    sp,
    sy,
    vf,
    vi,
    wj,
    xx,
    zw,
    zwj,
};

pub const Range = struct { first: u21, last: u21, class: BreakClass };

/// A plain codepoint span, for tables that carry no class of their own.
pub const CatRange = struct { first: u21, last: u21 };

