/// Binary search over `ranges`. Unassigned codepoints are `.xx` (LB1 maps
/// XX to AL); `breakClass` does that mapping, this does not.
pub fn classOf(cp: u21) BreakClass {
    var lo: usize = 0;
    var hi: usize = ranges.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const r = ranges[mid];
        if (cp < r.first) {
            hi = mid;
        } else if (cp > r.last) {
            lo = mid + 1;
        } else {
            return r.class;
        }
    }
    return .xx;
}

/// Characters the standard splits out of QU. These are ORIGINAL classes, not
/// behaviour: a global refinement lost 1.35 points, so the split is applied at
/// the rule that needs it and nowhere else.
pub const pi = [_]u21{ 0xab, 0x2018, 0x201c }; // « ' "
pub const pf = [_]u21{ 0xbb, 0x2019, 0x201d }; // » ' "

pub fn inSet(cp: u21, set: []const u21) bool {
    for (set) |s| if (s == cp) return true;
    return false;
}

/// LB1: resolve AI/XX/SG to AL, SA to AL (no dictionary breaking). SA that is
/// Mn/Mc should resolve to CM; without a category table it resolves to AL,
/// which is the same answer for every non-combining SA.
pub fn resolveClass(cp: u21) BreakClass {
    return switch (classOf(cp)) {
        .sa => if (isCombining(cp)) .cm else .al,
        // LB1's `_EastAsian` variant: an AI character that is also W/F behaves
        // as ID, not AL. Conformance assumes it, and it is what makes a wide
        // symbol behave like punctuation rather than like a letter.
        .ai => .al,
        .xx, .sg => .al,
        else => |c| c,
    };
}

/// Does the base character before any run of spaces ending at `i` belong to
/// `set`? Used where a rule keys on WHICH codepoint it was, not its class.
fn baseIn(f: []const Folded, i: usize, set: []const u21) bool {
    var j = i;
    while (j > 0) {
        j -= 1;
        if (f[j].cls == .sp) continue;
        var k = j;
        while (k > 0 and (f[k].resolved == .cm or f[k].resolved == .zwj)) k -= 1;
        for (set) |c| if (f[k].cp == c) return true;
        return false;
    }
    return false;
}

fn baseWasAi(f: []const Folded, i: usize) bool {
    var j = i;
    while (j > 0 and (f[j].resolved == .cm or f[j].resolved == .zwj)) j -= 1;
    return wasAi(f[j].cp);
}

fn wasAi(cp: u21) bool {
    return classOf(cp) == .ai;
}

pub fn isWide(cp: u21) bool {
    var lo: usize = 0;
    var hi = wide_ai.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (cp < wide_ai[mid].first) {
            hi = mid;
        } else if (cp > wide_ai[mid].last) {
            lo = mid + 1;
        } else return true;
    }
    return false;
}

